// ────────────────────────────────────────────────────────────────────────────
// Stub view builders — Builders 4/5/6 own the real ones. The stubs return a
// minimal Block Kit-shaped object plus a `__debug` field carrying the hints
// + proposalId so route tests can assert pass-through. The TODO below marks
// the integration point for Phase 1 merge.
//
// TODO(orchestrator): replace with imports from Builder 4/5/6 outputs after
// Phase 1 merge:
//   import { buildTaskModal } from "@/lib/slack/modals/task";
//   import { buildProjectModal } from "@/lib/slack/modals/project";
//   import { buildTeamMemberModal } from "@/lib/slack/modals/team-member";
// ────────────────────────────────────────────────────────────────────────────

interface ViewBuilderInput {
  kind: EntityKind;
  mode: CommandMode;
  proposalId: string;
  args: Record<string, unknown>;
  baselineHint?: string;
  multiMatchHint?: string;
  /** For edit-flow: prefilled current values from DB lookup. Single-match only. */
  currentValues?: Record<string, unknown>;
  /** For edit-flow multi-match: list of candidate entities for picker. */
  multiMatchCandidates?: { id: string; label: string }[];
}

function buildStubView(input: ViewBuilderInput): Record<string, unknown> {
  const header = pickHeader(input);
  return {
    type: "modal",
    callback_id: `runway_${input.mode}_${input.kind.replace("-", "_")}`,
    private_metadata: JSON.stringify({ proposalId: input.proposalId }),
    title: { type: "plain_text", text: header.slice(0, 24) },
    submit: { type: "plain_text", text: "Save" },
    close: { type: "plain_text", text: "Cancel" },
    blocks: [],
    // Test-only debug surface. Real view builders will not include this.
    __debug: {
      kind: input.kind,
      mode: input.mode,
      proposalId: input.proposalId,
      baselineHint: input.baselineHint,
      multiMatchHint: input.multiMatchHint,
      argsKeys: Object.keys(input.args),
      currentValuesKeys: input.currentValues
        ? Object.keys(input.currentValues)
        : undefined,
      multiMatchCandidates: input.multiMatchCandidates,
    },
  };
}

function pickHeader(input: ViewBuilderInput): string {
  if (input.mode === "create") {
    if (input.kind === "task") return MODAL_HEADERS.newTask;
    if (input.kind === "project") return MODAL_HEADERS.newProject;
    return MODAL_HEADERS.newTeamMember;
  }
  // edit mode — use a generic title when current values aren't loaded yet
  // (multi-match path); otherwise interpolate from currentValues.
  const cv = input.currentValues ?? {};
  if (input.kind === "task") {
    return MODAL_HEADERS.editTask(String(cv.title ?? ""));
  }
  if (input.kind === "project") {
    return MODAL_HEADERS.editProject(String(cv.name ?? ""));
  }
  return MODAL_HEADERS.editTeamMember(String(cv.fullName ?? cv.name ?? ""));
}

// ────────────────────────────────────────────────────────────────────────────

